async function run(task, tools, context) {
  const trace = [];

  // 1. Validate inputs
  const inputs = task.inputs || {};
  const { city, checkin, nights, budget } = inputs;

  if (
    !city || typeof city !== 'string' || !city.trim() ||
    !checkin || typeof checkin !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(checkin.trim()) ||
    typeof nights !== 'number' || !Number.isInteger(nights) || nights <= 0 ||
    typeof budget !== 'number' || isNaN(budget) || budget <= 0
  ) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: 'Please provide a valid city, checkin date (YYYY-MM-DD), number of nights (> 0), and total budget in INR (> 0).'
      },
      trace
    };
  }

  const cleanCity = city.trim();
  const cleanCheckin = checkin.trim();

  // Helper for resilient tool calls with retry
  async function callTool(name, args) {
    let retries = 0;
    while (true) {
      try {
        const result = await tools.call(name, args);
        return result;
      } catch (err) {
        if (err && err.name === 'ToolError') {
          const isTransient = ['UPSTREAM_503', 'TIMEOUT', 'NETWORK_ERROR'].includes(err.code);
          if (isTransient && retries < 2) {
            retries++;
            trace.push(`Retrying tool call ${name} due to ${err.code} (attempt ${retries + 1})`);
            continue;
          }
        }
        throw err;
      }
    }
  }

  // Helper to parse numeric values safely
  function parseNumber(val) {
    if (val === null || val === undefined) return 0;
    if (typeof val === 'number') return isNaN(val) ? 0 : val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/,/g, '').trim();
      const num = parseFloat(cleaned);
      return isNaN(num) ? 0 : num;
    }
    return 0;
  }

  // 2. Fetch Hotels & Attractions
  let hotelsRaw = [];
  let attractionsRaw = [];

  try {
    trace.push(`Searching hotels for city: ${cleanCity}`);
    const resHotels = await callTool('search_hotels', { city: cleanCity, checkin: cleanCheckin, nights });
    if (Array.isArray(resHotels)) {
      hotelsRaw = resHotels;
    }
  } catch (err) {
    trace.push(`Failed to search hotels: ${err.message || String(err)}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace
    };
  }

  try {
    trace.push(`Listing attractions for city: ${cleanCity}`);
    const resAttrs = await callTool('list_attractions', { city: cleanCity });
    if (Array.isArray(resAttrs)) {
      attractionsRaw = resAttrs;
    }
  } catch (err) {
    trace.push(`Failed to list attractions: ${err.message || String(err)}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace
    };
  }

  // Sanitize and validate hotels
  const hotels = [];
  for (const h of hotelsRaw) {
    if (!h || typeof h !== 'object') continue;
    const id = h.id ? String(h.id) : null;
    if (!id) continue;
    const pricePerNight = parseNumber(h.price_per_night);
    if (pricePerNight < 0) continue;
    hotels.push({
      id,
      name: h.name ? String(h.name) : id,
      price_per_night: pricePerNight,
      total_cost: pricePerNight * nights
    });
  }

  // Sanitize and validate attractions
  const attractions = [];
  for (const a of attractionsRaw) {
    if (!a || typeof a !== 'object') continue;
    const id = a.id ? String(a.id) : null;
    if (!id) continue;
    let entryFee = 0;
    if (a.entry_fee !== null && a.entry_fee !== undefined) {
      entryFee = parseNumber(a.entry_fee);
      if (entryFee < 0) entryFee = 0;
    }
    attractions.push({
      id,
      name: a.name ? String(a.name) : id,
      entry_fee: entryFee
    });
  }

  if (hotels.length === 0 || attractions.length < 2) {
    trace.push(`Insufficient options: ${hotels.length} valid hotels found, ${attractions.length} valid attractions found.`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace
    };
  }

  // 3. Find valid combination within budget
  // Search for the best plan (e.g. maximizing experience or just finding any valid plan within budget)
  let bestPlan = null;
  let minCost = Infinity;

  for (const hotel of hotels) {
    const hotelCost = hotel.total_cost;
    if (hotelCost > budget) continue;

    for (let i = 0; i < attractions.length; i++) {
      for (let j = i + 1; j < attractions.length; j++) {
        const attr1 = attractions[i];
        const attr2 = attractions[j];
        if (attr1.id === attr2.id) continue; // Ensure two different attractions

        const total = hotelCost + attr1.entry_fee + attr2.entry_fee;
        if (total <= budget) {
          // Select valid plan (could pick lowest cost or first valid)
          if (total < minCost) {
            minCost = total;
            bestPlan = {
              plan: [
                { kind: 'hotel', id: hotel.id, cost: hotelCost },
                { kind: 'attraction', id: attr1.id, cost: attr1.entry_fee },
                { kind: 'attraction', id: attr2.id, cost: attr2.entry_fee }
              ],
              total_cost: total
            };
          }
        }
      }
    }
  }

  if (!bestPlan) {
    trace.push('No combination of 1 hotel and 2 distinct attractions fits the budget.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace
    };
  }

  trace.push(`Successfully found a plan within budget (${bestPlan.total_cost} <= ${budget})`);
  return {
    status: 'success',
    answer: bestPlan,
    success_indicators: {},
    trace
  };
}

