async function run(task, tools, context) {
  const trace = [];
  const { city, checkin, nights, budget } = task.inputs;

  if (!city || !nights || budget == null) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Missing required inputs: city, nights, or budget.' },
      trace: ['Missing core inputs']
    };
  }

  // Helper to call tools with retry
  async function callTool(name, args) {
    let lastErr;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        return await tools.call(name, args);
      } catch (err) {
        lastErr = err;
        if (err && err.code === 'INVALID_ARGS') {
          throw err; // Do not retry invalid args
        }
      }
    }
    throw lastErr;
  }

  // 1. Search Hotels
  let hotels = [];
  try {
    trace.push(`Searching hotels for ${city}`);
    const res = await callTool('search_hotels', { city, checkin, nights });
    if (Array.isArray(res)) hotels = res;
  } catch (err) {
    trace.push(`search_hotels failed: ${err.message}`);
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  // 2. List Attractions
  let attractions = [];
  try {
    trace.push(`Listing attractions for ${city}`);
    const res = await callTool('list_attractions', { city });
    if (Array.isArray(res)) attractions = res;
  } catch (err) {
    trace.push(`list_attractions failed: ${err.message}`);
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  if (hotels.length === 0 || attractions.length < 2) {
    trace.push('Insufficient hotels or attractions found to build a plan.');
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // Clean/coerce hotel prices
  const cleanedHotels = hotels.map(h => {
    let ppn = h.price_per_night;
    if (typeof ppn === 'string') {
      ppn = Number(ppn.replace(/,/g, ''));
    }
    return { ...h, price_per_night: Number(ppn) || 0 };
  }).filter(h => h.price_per_night > 0);

  // Clean attractions entry fees (null means 0)
  const cleanedAttractions = attractions.map(a => {
    let fee = a.entry_fee;
    if (fee == null) fee = 0;
    if (typeof fee === 'string') {
      fee = Number(fee.replace(/,/g, ''));
    }
    return { ...a, entry_fee: Number(fee) || 0 };
  });

  let bestPlan = null;
  let minCost = Infinity;

  // Try combinations: 1 hotel + 2 distinct attractions
  for (const hotel of cleanedHotels) {
    const hotelCost = hotel.price_per_night * nights;
    if (hotelCost > budget) continue;

    for (let i = 0; i < cleanedAttractions.length; i++) {
      for (let j = i + 1; j < cleanedAttractions.length; j++) {
        const att1 = cleanedAttractions[i];
        const att2 = cleanedAttractions[j];
        const totalCost = hotelCost + att1.entry_fee + att2.entry_fee;

        if (totalCost <= budget && totalCost < minCost) {
          minCost = totalCost;
          bestPlan = {
            plan: [
              { kind: 'hotel', id: hotel.id, cost: hotelCost },
              { kind: 'attraction', id: att1.id, cost: att1.entry_fee },
              { kind: 'attraction', id: att2.id, cost: att2.entry_fee }
            ],
            total_cost: totalCost
          };
        }
      }
    }
  }

  if (!bestPlan) {
    trace.push('No combination of hotel and 2 attractions fits within the budget.');
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  trace.push(`Found valid plan with total cost ${bestPlan.total_cost}`);
  return {
    status: 'success',
    answer: bestPlan,
    success_indicators: { found: true },
    trace
  };
}

