// Production‑ready agent for planning a short city break
// Adheres to the specified interface contract and tool usage rules

async function run(task, tools, context) {
  const trace = [];
  const successIndicators = {};

  // ---------- Input validation ----------
  const { city, checkin, nights, budget } = task.inputs || {};

  if (typeof city !== 'string' || city.trim() === '') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Missing or invalid city name.' },
      trace
    };
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(checkin)) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'checkin must be in YYYY-MM-DD format.' },
      trace
    };
  }
  if (!Number.isInteger(nights) || nights <= 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'nights must be a positive integer.' },
      trace
    };
  }
  if (typeof budget !== 'number' || budget <= 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'budget must be a positive number.' },
      trace
    };
  }

  // ---------- Helper: tool call with retry ----------
  const transientCodes = new Set(['UPSTREAM_503', 'TIMEOUT']);
  async function callTool(name, args) {
    let attempts = 0;
    while (attempts < 3) {
      try {
        trace.push(`Calling tool ${name} (attempt ${attempts + 1})`);
        const result = await tools.call(name, args);
        trace.push(`Tool ${name} succeeded`);
        return result;
      } catch (err) {
        trace.push(`Tool ${name} failed: ${err.name || err}`);
        if (err.code && transientCodes.has(err.code)) {
          attempts += 1;
          if (attempts >= 3) throw err;
          trace.push(`Retrying ${name} due to transient error`);
        } else {
          throw err;
        }
      }
    }
  }

  // ---------- Helper: parse price strings ----------
  function parsePrice(val) {
    if (typeof val === 'number') return val;
    if (typeof val === 'string') {
      // Remove currency symbols, commas, spaces
      const cleaned = val.replace(/[^0-9.]/g, '');
      const num = parseFloat(cleaned);
      if (!isNaN(num)) return num;
    }
    return null;
  }

  // ---------- 1. Resolve city (optional, just to be safe) ----------
  let cityInfo;
  try {
    const geo = await callTool('geocode_city', { city, country_code: 'IN' });
    if (!Array.isArray(geo) || geo.length === 0) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'City not found.' },
        trace
      };
    }
    cityInfo = geo[0]; // use the most relevant
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'geocode_city failed.' },
      trace
    };
  }

  // ---------- 2. Search hotels ----------
  let hotels;
  try {
    const rawHotels = await callTool('search_hotels', { city: cityInfo.name, checkin, nights });
    if (!Array.isArray(rawHotels) || rawHotels.length === 0) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'No hotels found.' },
        trace
      };
    }
    hotels = rawHotels
      .map(h => ({
        id: h.id,
        name: h.name,
        price_per_night: parsePrice(h.price_per_night),
        rating: typeof h.rating === 'number' ? h.rating : null
      }))
      .filter(h => h.price_per_night !== null);
    if (hotels.length === 0) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'All hotel prices invalid.' },
        trace
      };
    }
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'search_hotels failed.' },
      trace
    };
  }

  // ---------- 3. List attractions ----------
  let attractions;
  try {
    const rawAttr = await callTool('list_attractions', { city: cityInfo.name });
    if (!Array.isArray(rawAttr) || rawAttr.length === 0) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'No attractions found.' },
        trace
      };
    }
    attractions = rawAttr
      .map(a => ({
        id: a.id,
        name: a.name,
        entry_fee: a.entry_fee === null ? 0 : Number(a.entry_fee),
        duration_hours: a.duration_hours,
        category: a.category
      }))
      .filter(a => typeof a.entry_fee === 'number' && !isNaN(a.entry_fee));
    if (attractions.length < 2) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'Less than two attractions available.' },
        trace
      };
    }
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'list_attractions failed.' },
      trace
    };
  }

  // ---------- 4. Find cheapest viable combination ----------
  // Sort hotels by total cost ascending
  hotels.sort((a, b) => a.price_per_night - b.price_per_night);
  // Sort attractions by entry fee ascending
  attractions.sort((a, b) => a.entry_fee - b.entry_fee);

  let bestPlan = null;
  for (const hotel of hotels) {
    const hotelCost = hotel.price_per_night * nights;
    // pick two cheapest attractions
    const attr1 = attractions[0];
    const attr2 = attractions[1];
    const totalCost = hotelCost + attr1.entry_fee + attr2.entry_fee;
    if (totalCost <= budget) {
      bestPlan = {
        plan: [
          { kind: 'hotel', id: hotel.id, cost: hotelCost },
          { kind: 'attraction', id: attr1.id, cost: attr1.entry_fee },
          { kind: 'attraction', id: attr2.id, cost: attr2.entry_fee }
        ],
        total_cost: totalCost
      };
      break;
    }
  }

  if (!bestPlan) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { message: 'No combination fits the budget.' },
      trace
    };
  }

  // ---------- 5. Return success ----------
  return {
    status: 'success',
    answer: bestPlan,
    success_indicators: {},
    trace
  };
}

