async function run(task, tools, context) {
  const trace = [];

  // Helper to safely call tools with up to 2 retries on transient/network errors
  async function callToolWithRetry(toolName, args) {
    let attempts = 0;
    while (attempts < 3) {
      attempts++;
      try {
        trace.push(`Calling tool ${toolName} (attempt ${attempts})`);
        const result = await tools.call(toolName, args);
        return result;
      } catch (err) {
        trace.push(`Error calling ${toolName}: ${err.message || err}`);
        const code = err && err.code ? err.code : '';
        const isTransient = code === 'UPSTREAM_503' || code === 'TIMEOUT' || code === 'NETWORK_ERROR' || code.startsWith('5');
        if (isTransient && attempts < 3) {
          continue;
        }
        throw err;
      }
    }
  }

  // Helper to parse numbers/numeric strings
  function parseNumber(val) {
    if (typeof val === 'number') return isNaN(val) ? null : val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/,/g, '').trim();
      const num = parseFloat(cleaned);
      return isNaN(num) ? null : num;
    }
    return null;
  }

  // 1. Validate inputs
  const inputs = task && task.inputs ? task.inputs : {};
  const { origin, city, date, nights, budget, min_rating } = inputs;

  const missingOrInvalid = [];
  if (!origin || typeof origin !== 'string' || !origin.trim()) missingOrInvalid.push('origin');
  if (!city || typeof city !== 'string' || !city.trim()) missingOrInvalid.push('city');

  // Date format check YYYY-MM-DD
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!date || typeof date !== 'string' || !dateRegex.test(date.trim())) missingOrInvalid.push('date');

  const parsedNights = parseNumber(nights);
  if (parsedNights === null || parsedNights <= 0 || !Number.isInteger(parsedNights)) missingOrInvalid.push('nights');

  const parsedBudget = parseNumber(budget);
  if (parsedBudget === null || parsedBudget <= 0) missingOrInvalid.push('budget');

  const parsedMinRating = parseNumber(min_rating);
  if (parsedMinRating === null || parsedMinRating < 0) missingOrInvalid.push('min_rating');

  if (missingOrInvalid.length > 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: `Missing or invalid input parameters: ${missingOrInvalid.join(', ')}.`
      },
      trace
    };
  }

  const cleanOrigin = origin.trim();
  const cleanCity = city.trim();
  const cleanDate = date.trim();

  // 2. Search flights and hotels in parallel / sequentially
  let flightsRaw = [];
  let hotelsRaw = [];

  try {
    const flightsRes = await callToolWithRetry('search_flights', {
      origin: cleanOrigin,
      destination: cleanCity,
      date: cleanDate
    });
    if (Array.isArray(flightsRes)) {
      flightsRaw = flightsRes;
    }
  } catch (err) {
    trace.push(`Failed to search flights: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Flight search failed: ${err.message}` },
      trace
    };
  }

  try {
    const hotelsRes = await callToolWithRetry('search_hotels', {
      city: cleanCity,
      checkin: cleanDate,
      nights: parsedNights
    });
    if (Array.isArray(hotelsRes)) {
      hotelsRaw = hotelsRes;
    }
  } catch (err) {
    trace.push(`Failed to search hotels: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Hotel search failed: ${err.message}` },
      trace
    };
  }

  // 3. Process and filter flights
  const validFlights = [];
  for (const f of flightsRaw) {
    if (!f || typeof f !== 'object') continue;
    const price = parseNumber(f.price);
    if (price === null || price < 0) continue;
    const flightId = f.id ? String(f.id) : null;
    if (!flightId) continue;

    validFlights.push({
      id: flightId,
      price: price
    });
  }

  // 4. Process and filter hotels
  // Minimum rating required (records without a rating do not qualify)
  const validHotels = [];
  for (const h of hotelsRaw) {
    if (!h || typeof h !== 'object') continue;
    const hotelId = h.id ? String(h.id) : null;
    if (!hotelId) continue;

    const rating = parseNumber(h.rating);
    if (rating === null || rating < parsedMinRating) continue;

    const pricePerNight = parseNumber(h.price_per_night);
    if (pricePerNight === null || pricePerNight < 0) continue;

    const totalHotelCost = pricePerNight * parsedNights;

    validHotels.push({
      id: hotelId,
      price_per_night: pricePerNight,
      total_cost: totalHotelCost
    });
  }

  trace.push(`Found ${validFlights.length} valid flights and ${validHotels.length} valid hotels matching constraints.`);

  if (validFlights.length === 0 || validHotels.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {
        reason: 'No eligible flights or hotels found matching criteria (date, rating, route).'
      },
      trace
    };
  }

  // 5. Find combination fitting within total budget (find minimum total cost combination)
  let bestCombination = null;
  let minTotalCost = Infinity;

  for (const flight of validFlights) {
    for (const hotel of validHotels) {
      const totalCost = flight.price + hotel.total_cost;
      if (totalCost <= parsedBudget) {
        if (totalCost < minTotalCost) {
          minTotalCost = totalCost;
          bestCombination = {
            flight,
            hotel,
            totalCost
          };
        }
      }
    }
  }

  if (!bestCombination) {
    trace.push('No combination fits within the specified budget.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {
        reason: `No flight + hotel combination fits within budget of ${parsedBudget} INR.`
      },
      trace
    };
  }

  // 6. Return success answer according to schema
  const answer = {
    plan: [
      {
        kind: 'flight',
        id: bestCombination.flight.id,
        cost: bestCombination.flight.price
      },
      {
        kind: 'hotel',
        id: bestCombination.hotel.id,
        cost: bestCombination.hotel.total_cost
      }
    ],
    total_cost: bestCombination.totalCost
  };

  return {
    status: 'success',
    answer,
    success_indicators: {
      budget: parsedBudget,
      total_cost: bestCombination.totalCost,
      savings: parsedBudget - bestCombination.totalCost
    },
    trace
  };
}

async function run(task, tools, context) {
  const { origin, city, date, nights, budget, min_rating } = task.inputs;
  const trace = [];

  // Helper for calling tools with retries
  async function callTool(name, args) {
    let attempts = 0;
    while (attempts < 3) {
      try {
        attempts++;
        return await tools.call(name, args);
      } catch (err) {
        if (attempts >= 3 || (err && err.code === 'NOT_FOUND')) {
          throw err;
        }
      }
    }
  }

  // Helper to parse price safely
  function parsePrice(val) {
    if (typeof val === 'number') return val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/,/g, '').trim();
      const num = parseFloat(cleaned);
      return isNaN(num) ? Infinity : num;
    }
    return Infinity;
  }

  let flights = [];
  try {
    trace.push(`Searching flights from ${origin} to ${city} on ${date}`);
    const res = await callTool('search_flights', { origin, destination: city, date });
    if (Array.isArray(res)) {
      flights = res;
    }
  } catch (err) {
    trace.push(`Flight search failed: ${err.message}`);
  }

  let hotels = [];
  try {
    trace.push(`Searching hotels in ${city}`);
    const res = await callTool('search_hotels', { city, checkin: date, nights });
    if (Array.isArray(res)) {
      hotels = res;
    }
  } catch (err) {
    trace.push(`Hotel search failed: ${err.message}`);
  }

  // Filter flights: must be valid price
  const validFlights = flights.filter(f => f && typeof f.price === 'number' && f.price >= 0);

  // Filter hotels: must have rating >= min_rating and valid price_per_night
  const validHotels = hotels.filter(h => {
    if (!h) return false;
    if (typeof h.rating !== 'number' || h.rating < min_rating) return false;
    const ppn = parsePrice(h.price_per_night);
    return ppn !== Infinity && ppn >= 0;
  });

  if (validFlights.length === 0 || validHotels.length === 0) {
    trace.push('No valid flights or hotels found meeting basic criteria.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No flights or qualifying hotels found' },
      trace
    };
  }

  let bestCombo = null;
  let minTotalCost = Infinity;

  for (const f of validFlights) {
    const flightCost = f.price;
    for (const h of validHotels) {
      const ppn = parsePrice(h.price_per_night);
      const hotelCost = ppn * nights;
      const totalCost = flightCost + hotelCost;

      if (totalCost <= budget && totalCost < minTotalCost) {
        minTotalCost = totalCost;
        bestCombo = {
          flight: f,
          hotel: h,
          hotelCost
        };
      }
    }
  }

  if (!bestCombo) {
    trace.push('Found flights and hotels, but no combination fits within the budget.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'All combinations exceed the budget' },
      trace
    };
  }

  trace.push(`Found optimal combination with total cost ${minTotalCost}`);
  return {
    status: 'success',
    answer: {
      plan: [
        {
          kind: 'flight',
          id: bestCombo.flight.id,
          cost: bestCombo.flight.price
        },
        {
          kind: 'hotel',
          id: bestCombo.hotel.id,
          cost: bestCombo.hotelCost
        }
      ],
      total_cost: minTotalCost
    },
    success_indicators: { optimal_cost: minTotalCost },
    trace
  };
}

async function run(task, tools, context) {
  const trace = [];
  const successIndicators = {};

  // ---------- Input validation ----------
  const { origin, city, date, nights, budget, min_rating } = task.inputs || {};

  const isNonEmptyString = (v) => typeof v === 'string' && v.trim() !== '';
  const isISODate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(v);
  const isPositiveInt = (v) => Number.isInteger(v) && v > 0;
  const isPositiveNumber = (v) => typeof v === 'number' && v > 0;

  if (!isNonEmptyString(origin) ||
      !isNonEmptyString(city) ||
      !isISODate(date) ||
      !isPositiveInt(nights) ||
      !isPositiveNumber(budget) ||
      !isPositiveNumber(min_rating)) {
    successIndicators.question = 'Missing or invalid inputs: ensure origin, city, date (YYYY-MM-DD), nights (positive integer), budget (positive number), min_rating (positive number).';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }

  // ---------- Helper for tool calls ----------
  const callTool = async (name, args) => {
    let attempts = 0;
    while (attempts < 3) { // 1 initial + 2 retries
      try {
        const result = await tools.call(name, args);
        return result;
      } catch (e) {
        attempts++;
        if (e.name !== 'ToolError' || !['UPSTREAM_503', 'TIMEOUT'].includes(e.code) || attempts >= 3) {
          throw e;
        }
        trace.push(`Retry ${attempts} for ${name} due to ${e.code}`);
      }
    }
  };

  // ---------- Geocode origin and destination ----------
  let originLoc, destLoc;
  try {
    const [originRes, destRes] = await Promise.all([
      callTool('geocode_city', { city: origin, country_code: 'IN' }),
      callTool('geocode_city', { city: city, country_code: 'IN' })
    ]);

    if (!originRes.length || !destRes.length) {
      return { status: 'infeasible', answer: null, success_indicators: {}, trace };
    }
    originLoc = originRes[0];
    destLoc = destRes[0];
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  // ---------- Search flights ----------
  let flights;
  try {
    flights = await callTool('search_flights', {
      origin: originLoc.name,
      destination: destLoc.name,
      date
    });
    if (!Array.isArray(flights) || flights.length === 0) {
      return { status: 'infeasible', answer: null, success_indicators: {}, trace };
    }
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  // ---------- Search hotels ----------
  let hotels;
  try {
    hotels = await callTool('search_hotels', {
      city: destLoc.name,
      checkin: date,
      nights
    });
    if (!Array.isArray(hotels) || hotels.length === 0) {
      return { status: 'infeasible', answer: null, success_indicators: {}, trace };
    }
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  // ---------- Validate and coerce tool outputs ----------
  const validFlights = flights.filter(f => {
    return f && f.id && typeof f.price === 'number' && f.price >= 0;
  });

  const validHotels = hotels
    .map(h => {
      if (!h || !h.id) return null;
      let price = h.price_per_night;
      if (typeof price === 'string') {
        price = price.replace(/[^0-9.]/g, '');
        price = parseFloat(price);
      }
      if (isNaN(price)) return null;
      const rating = typeof h.rating === 'number' ? h.rating : null;
      return { ...h, price_per_night: price, rating };
    })
    .filter(h => h && h.price_per_night >= 0 && h.rating !== null && h.rating >= min_rating);

  if (!validFlights.length || !validHotels.length) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // ---------- Find cheapest combination ----------
  let best = null;
  for (const f of validFlights) {
    for (const h of validHotels) {
      const hotelCost = h.price_per_night * nights;
      const total = f.price + hotelCost;
      if (total <= budget && (!best || total < best.total)) {
        best = {
          flight: f,
          hotel: h,
          total
        };
      }
    }
  }

  if (!best) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // ---------- Construct answer ----------
  const plan = [
    {
      kind: 'flight',
      id: best.flight.id,
      cost: best.flight.price
    },
    {
      kind: 'hotel',
      id: best.hotel.id,
      cost: best.hotel.price_per_night * nights
    }
  ];

  const answer = { plan, total_cost: best.total };
  return { status: 'success', answer, success_indicators: {}, trace };
}

async function run(task, tools, context) {
  const trace = [];

  // Helper for safe tool calls with up to 2 retries on transient errors
  async function callToolSafely(name, args) {
    let retries = 0;
    while (true) {
      try {
        const result = await tools.call(name, args);
        return result;
      } catch (err) {
        const isTransient = err && (err.code === 'UPSTREAM_503' || err.code === 'TIMEOUT' || err.name === 'TimeoutError');
        if (isTransient && retries < 2) {
          retries++;
          trace.push(`Retry ${retries} for tool ${name}`);
          continue;
        }
        throw err;
      }
    }
  }

  // Parse and validate numeric string
  function parseNumber(val) {
    if (typeof val === 'number') return isNaN(val) ? null : val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/,/g, '').trim();
      const parsed = parseFloat(cleaned);
      return isNaN(parsed) ? null : parsed;
    }
    return null;
  }

  // Input Validation
  const inputs = task && task.inputs ? task.inputs : {};
  const origin = typeof inputs.origin === 'string' ? inputs.origin.trim() : '';
  const city = typeof inputs.city === 'string' ? inputs.city.trim() : '';
  const date = typeof inputs.date === 'string' ? inputs.date.trim() : '';
  const nights = typeof inputs.nights === 'number' ? inputs.nights : parseInt(inputs.nights, 10);
  const budget = parseNumber(inputs.budget);

  // Validate YYYY-MM-DD format
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!origin || !city || !date || !dateRegex.test(date) || isNaN(nights) || nights <= 0 || budget === null || budget < 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: 'Please provide valid origin, destination city, date (YYYY-MM-DD), number of hotel nights (>0), and total budget in INR.'
      },
      trace
    };
  }

  let flights = [];
  let trains = [];
  let hotels = [];

  // Fetch transport and hotel options in parallel with error recovery
  try {
    trace.push(`Searching transport and hotels for origin=${origin}, city=${city}, date=${date}, nights=${nights}`);

    const [flightRes, trainRes, hotelRes] = await Promise.allSettled([
      callToolSafely('search_flights', { origin, destination: city, date }),
      callToolSafely('search_trains', { origin, destination: city, date }),
      callToolSafely('search_hotels', { city, checkin: date, nights })
    ]);

    if (flightRes.status === 'fulfilled' && Array.isArray(flightRes.value)) {
      flights = flightRes.value;
    } else if (flightRes.status === 'rejected') {
      trace.push(`search_flights failed: ${flightRes.reason.message || flightRes.reason}`);
    }

    if (trainRes.status === 'fulfilled' && Array.isArray(trainRes.value)) {
      trains = trainRes.value;
    } else if (trainRes.status === 'rejected') {
      trace.push(`search_trains failed: ${trainRes.reason.message || trainRes.reason}`);
    }

    if (hotelRes.status === 'fulfilled' && Array.isArray(hotelRes.value)) {
      hotels = hotelRes.value;
    } else if (hotelRes.status === 'rejected') {
      trace.push(`search_hotels failed: ${hotelRes.reason.message || hotelRes.reason}`);
    }
  } catch (err) {
    trace.push(`Unexpected error during data fetching: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace
    };
  }

  // Filter and normalize transport options
  const transportOptions = [];

  for (const item of flights) {
    if (!item || typeof item !== 'object') continue;
    const price = parseNumber(item.price);
    if (price !== null && price >= 0 && item.id) {
      transportOptions.push({
        kind: 'flight',
        id: String(item.id),
        cost: price
      });
    }
  }

  for (const item of trains) {
    if (!item || typeof item !== 'object') continue;
    const price = parseNumber(item.price);
    if (price !== null && price >= 0 && item.id) {
      transportOptions.push({
        kind: 'train',
        id: String(item.id),
        cost: price
      });
    }
  }

  // Filter and normalize hotel options
  const hotelOptions = [];
  for (const item of hotels) {
    if (!item || typeof item !== 'object') continue;
    const pricePerNight = parseNumber(item.price_per_night);
    if (pricePerNight !== null && pricePerNight >= 0 && item.id) {
      const totalHotelCost = pricePerNight * nights;
      hotelOptions.push({
        kind: 'hotel',
        id: String(item.id),
        cost: totalHotelCost
      });
    }
  }

  if (transportOptions.length === 0 || hotelOptions.length === 0) {
    trace.push(`No valid transport or hotel options found.`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace
    };
  }

  // Find the overall cheapest valid (transport + hotel) combination within budget
  let bestCombination = null;
  let minTotalCost = Infinity;

  for (const t of transportOptions) {
    for (const h of hotelOptions) {
      const totalCost = t.cost + h.cost;
      if (totalCost <= budget && totalCost < minTotalCost) {
        minTotalCost = totalCost;
        bestCombination = {
          transport: t,
          hotel: h,
          total_cost: totalCost
        };
      }
    }
  }

  if (!bestCombination) {
    trace.push(`All available options exceed the budget of INR ${budget}`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace
    };
  }

  trace.push(`Found optimal plan: ${bestCombination.transport.kind} (${bestCombination.transport.id}) + hotel (${bestCombination.hotel.id}) at total cost ${bestCombination.total_cost}`);

  return {
    status: 'success',
    answer: {
      plan: [
        {
          kind: bestCombination.transport.kind,
          id: bestCombination.transport.id,
          cost: bestCombination.transport.cost
        },
        {
          kind: bestCombination.hotel.kind,
          id: bestCombination.hotel.id,
          cost: bestCombination.hotel.cost
        }
      ],
      total_cost: bestCombination.total_cost
    },
    success_indicators: {
      budget_used: bestCombination.total_cost,
      budget_remaining: budget - bestCombination.total_cost
    },
    trace
  };
}

async function run(task, tools, context) {
  const trace = [];
  const { origin, city, date, nights, budget } = task.inputs;

  if (!origin || !city || !date || !nights || typeof budget !== 'number') {
