      success_indicators: { question: 'Missing required inputs: origin, city, date, nights, or budget.' },
      trace: ['Missing inputs']
    };
  }

  async function callToolWithRetry(name, args) {
    let lastErr;
    for (let attempt = 0; attempts < 3; attempt++) {
      try {
        return await tools.call(name, args);
      } catch (err) {
        lastErr = err;
        if (err && err.code === 'NOT_FOUND') {
          throw err;
        }
      }
    }
    throw lastErr;
  }

  let flights = [];
  try {
    const res = await callToolWithRetry('search_flights', { origin, destination: city, date });
    if (Array.isArray(res)) flights = res;
    trace.push(`Found ${flights.length} flights`);
  } catch (err) {
    trace.push(`Flights search failed: ${err.message}`);
  }

  let trains = [];
  try {
    const res = await callToolWithRetry('search_trains', { origin, destination: city, date });
    if (Array.isArray(res)) trains = res;
    trace.push(`Found ${trains.length} trains`);
  } catch (err) {
    trace.push(`Trains search failed: ${err.message}`);
  }

  let hotels = [];
  try {
    const res = await callToolWithRetry('search_hotels', { city, checkin: date, nights });
    if (Array.isArray(res)) hotels = res;
    trace.push(`Found ${hotels.length} hotels`);
  } catch (err) {
    trace.push(`Hotels search failed: ${err.message}`);
  }

  const transportOptions = [];
  for (const f of flights) {
    const price = Number(String(f.price).replace(/,/g, ''));
    if (!isNaN(price)) {
      transportOptions.push({ kind: 'flight', id: f.id, cost: price });
    }
  }
  for (const t of trains) {
    const price = Number(String(t.price).replace(/,/g, ''));
    if (!isNaN(price)) {
      transportOptions.push({ kind: 'train', id: t.id, cost: price });
    }
  }

  const hotelOptions = [];
  for (const h of hotels) {
    const ppn = Number(String(h.price_per_night).replace(/,/g, ''));
    if (!isNaN(ppn)) {
      hotelOptions.push({ kind: 'hotel', id: h.id, cost: ppn * nights });
    }
  }

  if (transportOptions.length === 0 || hotelOptions.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No transport or hotels found.' },
      trace
    };
  }

  let bestCombo = null;
  let minCost = Infinity;

  for (const t of transportOptions) {
    for (const h of hotelOptions) {
      const total = t.cost + h.cost;
      if (total < minCost) {
        minCost = total;
        bestCombo = [t, h];
      }
    }
  }

  if (!bestCombo || minCost > budget) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Cheapest combination exceeds budget or none found.' },
      trace
    };
  }

  return {
    status: 'success',
    answer: {
      plan: bestCombo,
      total_cost: minCost
    },
    success_indicators: { matched: true },
    trace
  };
}

async function run(task, tools, context) {
  const trace = [];
  const successIndicators = {};

  // ---------- Input validation ----------
  const { origin, city, date, nights, budget } = task.inputs || {};

  function isNonEmptyString(val) {
    return typeof val === 'string' && val.trim() !== '';
  }

  if (!isNonEmptyString(origin)) {
    successIndicators.question = 'Missing or invalid origin city.';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  if (!isNonEmptyString(city)) {
    successIndicators.question = 'Missing or invalid destination city.';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  if (!isNonEmptyString(date) || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    successIndicators.question = 'Missing or invalid date (YYYY-MM-DD).';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  if (!Number.isInteger(nights) || nights <= 0) {
    successIndicators.question = 'Nights must be a positive integer.';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  if (typeof budget !== 'number' || budget <= 0) {
    successIndicators.question = 'Budget must be a positive number.';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }

  // ---------- Helper for tool calls ----------
  async function callWithRetries(name, args, maxRetries = 2) {
    let attempts = 0;
    while (attempts <= maxRetries) {
      try {
        trace.push(`Calling ${name} (attempt ${attempts + 1})`);
        const result = await tools.call(name, args);
        trace.push(`Result from ${name}: ${JSON.stringify(result)}`);
        return result;
      } catch (err) {
        if (err.name === 'ToolError' && ['UPSTREAM_503', 'TIMEOUT'].includes(err.code)) {
          attempts += 1;
          if (attempts > maxRetries) throw err;
          trace.push(`Transient error ${err.code} on ${name}, retrying...`);
        } else {
          trace.push(`Non-retryable error on ${name}: ${err.message}`);
          throw err;
        }
      }
    }
  }

  // ---------- Resolve cities ----------
  let originLocs, destLocs;
  try {
    originLocs = await callWithRetries('geocode_city', { city: origin, country_code: 'IN' });
    destLocs = await callWithRetries('geocode_city', { city, country_code: 'IN' });
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  if (!originLocs.length || !destLocs.length) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  const originName = originLocs[0].name;
  const destName = destLocs[0].name;

  // ---------- Search transport ----------
  let flights = [], trains = [];
  try {
    flights = await callWithRetries('search_flights', { origin: originName, destination: destName, date });
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }
  try {
    trains = await callWithRetries('search_trains', { origin: originName, destination: destName, date });
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  // ---------- Validate transport data ----------
  function validateTransport(arr, mode) {
    return arr.filter(item => {
      return item &&
        typeof item.id === 'string' &&
        item.mode === mode &&
        typeof item.price === 'number' &&
        typeof item.origin === 'string' &&
        typeof item.destination === 'string';
    });
  }
  flights = validateTransport(flights, 'flight');
  trains = validateTransport(trains, 'train');

  // ---------- Search hotels ----------
  let hotels = [];
  try {
    hotels = await callWithRetries('search_hotels', { city: destName, checkin: date, nights });
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
  }

  // ---------- Validate hotel data ----------
  function coercePrice(val) {
    if (typeof val === 'number') return val;
    if (typeof val === 'string') {
      const num = parseFloat(val.replace(/[^0-9.]/g, ''));
      return isNaN(num) ? null : num;
    }
    return null;
  }

  hotels = hotels
    .map(h => ({
      id: h.id,
      name: h.name,
      city: h.city,
      price_per_night: coercePrice(h.price_per_night),
      rating: typeof h.rating === 'number' ? h.rating : null,
      veg_friendly: !!h.veg_friendly
    }))
    .filter(h => h.id && h.name && h.city && typeof h.price_per_night === 'number');

  if (!hotels.length) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // ---------- Find cheapest transport ----------
  const cheapestFlight = flights.reduce((best, cur) => !best || cur.price < best.price ? cur : best, null);
  const cheapestTrain = trains.reduce((best, cur) => !best || cur.price < best.price ? cur : best, null);

  const transportOptions = [];
  if (cheapestFlight) transportOptions.push({ ...cheapestFlight, total_price: cheapestFlight.price });
  if (cheapestTrain) transportOptions.push({ ...cheapestTrain, total_price: cheapestTrain.price });

  if (!transportOptions.length) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // ---------- Find cheapest hotel ----------
  const cheapestHotel = hotels.reduce((best, cur) => !best || cur.price_per_night < best.price_per_night ? cur : best, null);
  if (!cheapestHotel) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }
  const hotelTotal = cheapestHotel.price_per_night * nights;

  // ---------- Evaluate combinations ----------
  let bestPlan = null;
  for (const transport of transportOptions) {
    const total = transport.total_price + hotelTotal;
    if (total <= budget) {
      const plan = [
        { kind: 'hotel', id: cheapestHotel.id, cost: hotelTotal },
        { kind: transport.mode, id: transport.id, cost: transport.total_price }
      ];
      if (!bestPlan || total < bestPlan.total_cost) {
        bestPlan = { plan, total_cost: total };
      }
    }
  }

  if (!bestPlan) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // ---------- Success ----------
  return {
    status: 'success',
    answer: bestPlan,
    success_indicators: {},
    trace
  };
}

