  // Coerce count and budget if provided as strings
  if (typeof count === 'string') count = parseInt(count.replace(/,/g, ''), 10);
  if (typeof budget === 'string') budget = parseFloat(budget.replace(/,/g, ''));

  if (!city || count === undefined || count === null || isNaN(count) || count <= 0 || budget === undefined || budget === null || isNaN(budget) || budget < 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: 'Please provide a valid city name, a positive count of restaurants, and a non-negative budget in INR.'
      },
      trace
    };
  }

  // 2. Query search_restaurants for veg places
  let rawRestaurants = null;
  try {
    // Try requesting veg_only = true first
    rawRestaurants = await callSearchRestaurants({ city, veg_only: true });
  } catch (err) {
    // Fallback: try searching without veg_only filter if tool call failed or veg_only argument wasn't supported
    try {
      rawRestaurants = await callSearchRestaurants({ city });
    } catch (err2) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Failed to fetch restaurants: ${err2.message || err2}` },
        trace
      };
    }
  }

  if (!Array.isArray(rawRestaurants)) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Tool output format invalid (expected array of restaurants).' },
      trace
    };
  }

  // 3. Parse, validate, filter, and sanitize restaurant records
  const validVegRestaurants = [];
  const seenIds = new Set();

  for (const item of rawRestaurants) {
    if (!item || typeof item !== 'object') continue;

    // Sanitize and parse fields
    const id = item.id ? String(item.id).trim() : '';
    if (!id || seenIds.has(id)) continue;

    const isVeg = item.veg === true || String(item.veg).toLowerCase() === 'true';
    if (!isVeg) continue;

    let cost = item.avg_cost_for_two;
    if (typeof cost === 'string') {
      cost = parseFloat(cost.replace(/,/g, ''));
    }
    if (typeof cost !== 'number' || isNaN(cost) || cost < 0) continue;

    let rating = item.rating;
    if (typeof rating === 'string') rating = parseFloat(rating);
    if (typeof rating !== 'number' || isNaN(rating)) rating = 0;

    seenIds.add(id);
    validVegRestaurants.push({
      id,
      cost,
      rating
    });
  }

  // 4. Check if enough distinct vegetarian restaurants are available
  if (validVegRestaurants.length < count) {
    trace.push(`Found only ${validVegRestaurants.length} valid veg restaurants, needed ${count}.`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {
        reason: `Not enough distinct vegetarian restaurants found in ${city}. Requested: ${count}, Found: ${validVegRestaurants.length}.`
      },
      trace
    };
  }

  // 5. Select `count` restaurants that satisfy the budget
  // Sort ascending by cost to maximize probability of finding a set within budget
  validVegRestaurants.sort((a, b) => a.cost - b.cost);

  const selected = validVegRestaurants.slice(0, count);
  const totalCost = selected.reduce((sum, r) => sum + r.cost, 0);

  if (totalCost > budget) {
    trace.push(`Cheapest ${count} veg restaurants sum to ${totalCost} INR, exceeding budget of ${budget} INR.`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {
        reason: `Minimum cost for ${count} vegetarian restaurants in ${city} is ${totalCost} INR, which exceeds the budget of ${budget} INR.`
      },
      trace
    };
  }

  // 6. Build success plan matching schema
  const plan = selected.map(r => ({
    kind: 'restaurant',
    id: r.id,
    cost: r.cost
  }));

  return {
    status: 'success',
    answer: {
      plan,
      total_cost: totalCost
    },
    success_indicators: {
      city,
      count_selected: plan.length,
      budget,
      total_cost: totalCost
    },
    trace
  };
}

