async function run(task, tools, context) {
  // ---------- Helper utilities ----------
  const trace = [];
  const successIndicators = {};

  function log(msg) { trace.push(msg); }

  // Validate task inputs
  const { city, count, budget } = task.inputs || {};
  if (typeof city !== 'string' || city.trim() === '') {
    return { status: 'needs_clarification', answer: null, success_indicators: { question: 'Missing or invalid city' }, trace };
  }
  if (!Number.isInteger(count) || count <= 0) {
    return { status: 'needs_clarification', answer: null, success_indicators: { question: 'Missing or invalid count' }, trace };
  }
  if (typeof budget !== 'number' || budget <= 0) {
    return { status: 'needs_clarification', answer: null, success_indicators: { question: 'Missing or invalid budget' }, trace };
  }

  // ---------- Tool call wrapper ----------
  async function callWithRetry(toolName, args, retries = 2) {
    let attempt = 0;
    while (attempt <= retries) {
      try {
        log(`Calling ${toolName} (attempt ${attempt + 1})`);
        const result = await tools.call(toolName, args);
        log(`Success from ${toolName}`);
        return result;
      } catch (e) {
        if (e.name === 'ToolError' && ['TIMEOUT', 'UPSTREAM_503'].includes(e.code)) {
          log(`Transient error ${e.code} from ${toolName}`);
          if (attempt === retries) throw e;
        } else {
          log(`Non-retryable error from ${toolName}: ${e.message}`);
          throw e;
        }
      }
      attempt++;
    }
  }

  // ---------- Fetch restaurants ----------
  let restaurants;
  try {
    restaurants = await callWithRetry('search_restaurants', { city, veg_only: true });
  } catch (e) {
    return { status: 'failed_gracefully', answer: null, success_indicators: { error: e.message }, trace };
  }

  // Validate tool output
  if (!Array.isArray(restaurants)) {
    return { status: 'failed_gracefully', answer: null, success_indicators: { error: 'search_restaurants did not return an array' }, trace };
  }

  const validRestaurants = [];
  for (const r of restaurants) {
    if (
      typeof r.id === 'string' &&
      typeof r.avg_cost_for_two === 'number' &&
      typeof r.veg === 'boolean'
    ) {
      validRestaurants.push(r);
    } else {
      log(`Skipping invalid restaurant entry: ${JSON.stringify(r)}`);
    }
  }

  if (validRestaurants.length < count) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // ---------- Plan selection ----------
  // Sort by avg_cost_for_two ascending to maximize chance of fitting budget
  validRestaurants.sort((a, b) => a.avg_cost_for_two - b.avg_cost_for_two);

  const selected = [];
  let totalCost = 0;
  for (let i = 0; i < count; i++) {
    const r = validRestaurants[i];
    selected.push({ kind: 'restaurant', id: r.id, cost: r.avg_cost_for_two });
    totalCost += r.avg_cost_for_two;
  }

  if (totalCost > budget) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  // ---------- Return success ----------
  const answer = {
    plan: selected,
    total_cost: totalCost
  };

  return {
    status: 'success',
    answer,
    success_indicators: {},
    trace
  };
}

async function run(task, tools, context) {
  const trace = [];

  // Helper: tool caller with up to 2 retries on transient errors
  async function callTool(name, args) {
    let retries = 0;
    while (true) {
      try {
        trace.push(`Calling tool ${name} with ${JSON.stringify(args)}`);
        const res = await tools.call(name, args);
        return res;
      } catch (err) {
        if (err && err.name === 'ToolError') {
          const code = err.code || '';
          const isTransient = code.startsWith('UPSTREAM_') || code === 'TIMEOUT' || code === 'RATE_LIMIT';
          if (isTransient && retries < 2) {
            retries++;
            trace.push(`Retrying tool ${name} due to ${code} (attempt ${retries})`);
            continue;
          }
        }
        throw err;
      }
    }
  }

  // Parse & Validate Task Inputs
  const city = task?.inputs?.city;
  const checkin = task?.inputs?.checkin;
  const budget = task?.inputs?.budget;

  if (!city || typeof city !== 'string' || !city.trim()) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid Indian city name.' },
      trace
    };
  }

  if (!checkin || typeof checkin !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(checkin.trim())) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid check-in date in YYYY-MM-DD format.' },
      trace
    };
  }

  let numBudget = Number(budget);
  if (typeof budget === 'string') {
    numBudget = Number(budget.replace(/,/g, ''));
  }
  if (budget === undefined || budget === null || isNaN(numBudget) || numBudget <= 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid numeric budget in INR.' },
      trace
    };
  }

  const cleanCity = city.trim();

  // Helper numeric parser
  function parseCost(val) {
    if (val === null || val === undefined) return 0;
    if (typeof val === 'number') return isNaN(val) ? 0 : val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/[^0-9.]/g, '');
      const parsed = parseFloat(cleaned);
      return isNaN(parsed) ? 0 : parsed;
    }
    return 0;
  }

  // Execute tool calls sequentially / gracefully
  let hotels = [];
  let restaurants = [];
  let attractions = [];

  try {
    const rawHotels = await callTool('search_hotels', { city: cleanCity, checkin: checkin.trim(), nights: 1 });
    if (Array.isArray(rawHotels)) {
      hotels = rawHotels;
    }
  } catch (err) {
    trace.push(`Failed search_hotels: ${err.message}`);
  }

  try {
    const rawRestaurants = await callTool('search_restaurants', { city: cleanCity, veg_only: true });
    if (Array.isArray(rawRestaurants)) {
      restaurants = rawRestaurants;
    }
  } catch (err) {
    trace.push(`Failed search_restaurants: ${err.message}`);
  }

  try {
    const rawAttractions = await callTool('list_attractions', { city: cleanCity });
    if (Array.isArray(rawAttractions)) {
      attractions = rawAttractions;
    }
  } catch (err) {
    trace.push(`Failed list_attractions: ${err.message}`);
  }

  // Filter and normalize candidates
  // 1. Veg-friendly hotels (veg_friendly === true)
  const validHotels = hotels
    .filter(h => h && h.id && (h.veg_friendly === true || String(h.veg_friendly).toLowerCase() === 'true'))
    .map(h => ({
      id: String(h.id),
      cost: parseCost(h.price_per_night) // nights = 1
    }))
    .filter(h => h.cost >= 0);

  // 2. Veg restaurants (veg === true or search_restaurants veg_only filter)
  const validRestaurants = restaurants
    .filter(r => r && r.id && (r.veg === true || String(r.veg).toLowerCase() === 'true' || r.veg === undefined))
    .map(r => ({
      id: String(r.id),
      cost: parseCost(r.avg_cost_for_two)
    }))
    .filter(r => r.cost >= 0);

  // 3. Attractions
  const validAttractions = attractions
    .filter(a => a && a.id)
    .map(a => ({
      id: String(a.id),
      cost: parseCost(a.entry_fee)
    }))
    .filter(a => a.cost >= 0);

  if (validHotels.length === 0 || validRestaurants.length === 0 || validAttractions.length === 0) {
    trace.push(`Missing valid candidates. Hotels: ${validHotels.length}, Restaurants: ${validRestaurants.length}, Attractions: ${validAttractions.length}`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Could not find required veg-friendly hotel, vegetarian restaurant, or attraction in the specified city.' },
      trace
    };
  }

  // Find a combination within budget
  let bestPlan = null;
  let minCost = Infinity;

  for (const h of validHotels) {
    for (const r of validRestaurants) {
      for (const a of validAttractions) {
        const totalCost = h.cost + r.cost + a.cost;
        if (totalCost <= numBudget && totalCost < minCost) {
          minCost = totalCost;
          bestPlan = {
            plan: [
              { kind: 'hotel', id: h.id, cost: h.cost },
              { kind: 'attraction', id: a.id, cost: a.cost },
              { kind: 'restaurant', id: r.id, cost: r.cost }
            ],
            total_cost: totalCost
          };
        }
      }
    }
  }

  if (!bestPlan) {
    trace.push(`No combination within budget ${numBudget}`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No valid combination of hotel, attraction, and restaurant fits within the total budget.' },
      trace
    };
  }

  return {
    status: 'success',
    answer: bestPlan,
    success_indicators: {
      budget: numBudget,
      total_cost: bestPlan.total_cost,
      savings: numBudget - bestPlan.total_cost
    },
    trace
  };
}

async function run(task, tools, context) {
  const trace = [];
  const city = task.inputs.city;
  const checkin = task.inputs.checkin;
  const budget = task.inputs.budget;

  function parsePrice(val) {
    if (typeof val === 'number') return val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/[^0-9.]/g, '');
      const num = parseFloat(cleaned);
      return isNaN(num) ? 0 : num;
    }
    return 0;
  }

  // 1. Verify city with geocode_city first to ensure it's valid
  try {
    trace.push(`Geocoding city: ${city}`);
    const geo = await tools.call('geocode_city', { city: city, country_code: 'IN' });
    if (!geo || geo.length === 0) {
      trace.push('City not found or invalid.');
      return {
        status: 'infeasible',
        answer: null,
        success_indicators: { reason: 'City not found' },
        trace
      };
    }
  } catch (err) {
    trace.push(`Geocode error: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  // 2. Fetch hotels, restaurants, attractions concurrently or sequentially
  let hotels = [];
  let restaurants = [];
  let attractions = [];

  try {
    trace.push('Searching hotels, restaurants, attractions');
    const [hRes, rRes, aRes] = await Promise.all([
      tools.call('search_hotels', { city: city, checkin: checkin, nights: 1 }).catch(() => []),
      tools.call('search_restaurants', { city: city, veg_only: false }).catch(() => []),
      tools.call('list_attractions', { city: city }).catch(() => [])
    ]);

    hotels = hRes || [];
    restaurants = rRes || [];
    attractions = aRes || [];
  } catch (err) {
    trace.push(`Error fetching data: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  // Filter veg-friendly hotels
  const vegHotels = hotels.filter(h => h.veg_friendly === true);
  // Filter vegetarian restaurants (veg === true or cuisine indicates veg, tool has veg flag)
  const vegRestaurants = restaurants.filter(r => r.veg === true);

  if (vegHotels.length === 0 || vegRestaurants.length === 0 || attractions.length === 0) {
    trace.push('Missing required categories (veg hotel, veg restaurant, or attraction).');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Missing mandatory option categories' },
      trace
    };
  }

  // Find valid combination within budget
  // hotel cost = price_per_night * 1 (nights=1)
  // restaurant cost = avg_cost_for_two
  // attraction cost = entry_fee (if null, 0)
  let bestPlan = null;
  let minCost = Infinity;

  for (const h of vegHotels) {
    const hCost = parsePrice(h.price_per_night);
    for (const r of vegRestaurants) {
      const rCost = parsePrice(r.avg_cost_for_two);
      for (const a of attractions) {
        const aCost = a.entry_fee !== null ? parsePrice(a.entry_fee) : 0;
        const total = hCost + rCost + aCost;

        if (total <= budget) {
          if (total < minCost) {
            minCost = total;
            bestPlan = [
              { kind: 'hotel', id: h.id, cost: hCost },
              { kind: 'attraction', id: a.id, cost: aCost },
              { kind: 'restaurant', id: r.id, cost: rCost }
            ];
          }
        }
      }
    }
  }

  if (!bestPlan) {
    trace.push('No combination found within budget.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Budget exceeded for all combinations' },
      trace
    };
  }

  trace.push('Successfully found a valid plan within budget.');
  return {
    status: 'success',
    answer: {
      plan: bestPlan,
      total_cost: minCost
    },
    success_indicators: { matched: true },
    trace
  };
}

