/**
 * Agent to total forecast precipitation for an Indian city.
 * Returns the sum over the requested number of days in the requested unit.
 */
async function run(task, tools, context) {
  const trace = [];

  // ----- Helper utilities -----
  const isInteger = (n) => Number.isInteger(n);
  const isNumber = (n) => typeof n === 'number' && !Number.isNaN(n);
  const toNumber = (v) => {
    if (isNumber(v)) return v;
    if (typeof v === 'string') {
      // allow commas as thousand separators
      const cleaned = v.replace(/,/g, '');
      const num = Number(cleaned);
      return isNaN(num) ? NaN : num;
    }
    return NaN;
  };
  const retryTool = async (name, args, maxRetries = 2) => {
    let attempt = 0;
    while (true) {
      try {
        const res = await tools.call(name, args);
        return res;
      } catch (e) {
        if (e && e.name === 'ToolError' && attempt < maxRetries) {
          attempt++;
          trace.push(`Retry ${attempt} for tool ${name} due to ${e.code}`);
          continue;
        }
        throw e;
      }
    }
  };
  const mmToInches = (mm) => mm * 0.0393701;

  // ----- Input validation -----
  const inputs = task.inputs || {};
  const { city, days, unit } = inputs;

  if (typeof city !== 'string' || city.trim() === '') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid Indian city name.' },
      trace,
    };
  }
  if (!isInteger(days) || days < 1 || days > 16) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Days must be an integer between 1 and 16.' },
      trace,
    };
  }
  if (unit !== 'mm' && unit !== 'in') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: "Unit must be either 'mm' or 'in'." },
      trace,
    };
  }

  // ----- Resolve city to coordinates -----
  let geoResults;
  try {
    geoResults = await retryTool('geocode_city', { city: city.trim(), country_code: 'IN' });
    trace.push('geocode_city succeeded');
  } catch (e) {
    trace.push(`geocode_city failed: ${e.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Unable to resolve city.' },
      trace,
    };
  }

  if (!Array.isArray(geoResults) || geoResults.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'City not found in India.' },
      trace,
    };
  }

  const { latitude, longitude } = geoResults[0];
  if (!isNumber(latitude) || !isNumber(longitude)) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Invalid coordinates from geocode.' },
      trace,
    };
  }

  // ----- Get weather forecast -----
  let forecast;
  try {
    forecast = await retryTool('weather_forecast', {
      latitude,
      longitude,
      days,
    });
    trace.push('weather_forecast succeeded');
  } catch (e) {
    trace.push(`weather_forecast failed: ${e.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Unable to retrieve weather forecast.' },
      trace,
    };
  }

  // Validate forecast structure
  if (
    !forecast ||
    typeof forecast !== 'object' ||
    !Array.isArray(forecast.daily) ||
    forecast.daily.length < days
  ) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Malformed forecast data.' },
      trace,
    };
  }

  // ----- Sum precipitation -----
  let totalMm = 0;
  for (let i = 0; i < days; i++) {
    const day = forecast.daily[i];
    if (!day || typeof day !== 'object' || day.precipitation_mm == null) {
      trace.push(`Missing precipitation data for day index ${i}`);
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'Incomplete precipitation data.' },
        trace,
      };
    }
    const precip = toNumber(day.precipitation_mm);
    if (Number.isNaN(precip) || precip < 0) {
      trace.push(`Invalid precipitation value "${day.precipitation_mm}" on day ${day.date}`);
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'Invalid precipitation value.' },
        trace,
      };
    }
    totalMm += precip;
  }

  // ----- Convert unit if needed -----
  let finalValue = totalMm;
  if (unit === 'in') {
    finalValue = mmToInches(totalMm);
  }
  // Round to 2 decimal places for readability
  finalValue = Math.round(finalValue * 100) / 100;

  // ----- Return success -----
  return {
    status: 'success',
    answer: { value: finalValue, unit },
    success_indicators: { total_precipitation_mm: totalMm, days_considered: days },
    trace,
  };
}

