        }
        if (typeof price === 'number' && !isNaN(price)) {
            totalPriceInr += price;
            count++;
        }
    }

    if (count === 0) {
        return {
            status: 'infeasible',
            answer: null,
            success_indicators: { reason: 'No valid prices found for filtered hotels' },
            trace
        };
    }

    const avgPriceInr = totalPriceInr / count;
    trace.push(`Average price in INR: ${avgPriceInr} across ${count} hotels`);

    // Convert currency to USD
    let conversion;
    try {
        trace.push('Converting INR to USD');
        conversion = await callToolWithRetry('convert_currency', {
            amount: avgPriceInr,
            from: 'INR',
            to: 'USD'
        });
    } catch (err) {
        return {
            status: 'failed_gracefully',
            answer: null,
            success_indicators: { error: err.message },
            trace
        };
    }

