    };
  }
  if (typeof min_rating !== 'number' || !Number.isFinite(min_rating)) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Missing or invalid min_rating.' },
      trace
    };
  }

  // ---------- Helper: safe tool call ----------
  async function safeCall(name, args) {
    const maxRetries = 2;
    let attempt = 0;
    while (attempt <= maxRetries) {
      try {
        const result = await tools.call(name, args);
        trace.push(`tool ${name} succeeded on attempt ${attempt + 1}`);
        return result;
      } catch (e) {
        if (e.name === 'ToolError' && ['UPSTREAM_503', 'TIMEOUT'].includes(e.code)) {
          if (attempt === maxRetries) {
            trace.push(`tool ${name} failed after ${maxRetries + 1} attempts: ${e.code}`);
            throw e;
          }
          attempt++;
          trace.push(`retrying tool ${name} (attempt ${attempt + 1}) due to ${e.code}`);
        } else {
          trace.push(`tool ${name} threw non-retryable error: ${e.message}`);
          throw e;
        }
      }
    }
  }

  // ---------- Geocode city ----------
  let geoResults;
  try {
    geoResults = await safeCall('geocode_city', { city, country_code: 'IN' });
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `geocode_city failed: ${e.message}` },
      trace
    };
  }
  if (!Array.isArray(geoResults) || geoResults.length === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'City not found in India.' },
      trace
    };
  }
  // Use the most relevant match
  const targetCity = geoResults[0].name;

  // ---------- Search hotels ----------
  let hotels;
  try {
    hotels = await safeCall('search_hotels', { city: targetCity });
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `search_hotels failed: ${e.message}` },
      trace
    };
  }
  if (!Array.isArray(hotels) || hotels.length === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'No hotels found.' },
      trace
    };
  }

  // ---------- Filter and validate hotels ----------
  const validHotels = [];
  for (const h of hotels) {
    // rating must exist and >= min_rating
    if (typeof h.rating !== 'number' || !Number.isFinite(h.rating)) continue;
    if (h.rating < min_rating) continue;

    // price_per_night must be number or numeric string
    let price = h.price_per_night;
    if (typeof price === 'string') {
      // Remove commas, currency symbols
      const cleaned = price.replace(/[^0-9.]/g, '');
      price = parseFloat(cleaned);
    }
    if (typeof price !== 'number' || !Number.isFinite(price)) continue;

    validHotels.push({ id: h.id, price });
  }

  if (validHotels.length === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'No hotels meet rating requirement.' },
      trace
    };
  }

  // ---------- Compute average price in INR ----------
  const avgInr = validHotels.reduce((sum, h) => sum + h.price, 0) / validHotels.length;

  // ---------- Convert to USD ----------
  let conversion;
  try {
    conversion = await safeCall('convert_currency', {
      amount: avgInr,
      from: 'INR',
      to: 'USD'
    });
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `convert_currency failed: ${e.message}` },
      trace
    };
  }

  // Validate conversion output
  if (
    typeof conversion.converted !== 'number' ||
    !Number.isFinite(conversion.converted)
  ) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Invalid conversion result.' },
      trace
    };
  }

  // ---------- Return success ----------
  return {
    status: 'success',
    answer: { value: conversion.converted, unit: 'USD' },
    success_indicators: { average_inr: avgInr, rate: conversion.rate },
    trace
  };
}

