async function run(task, tools, context) {
  const trace = [];

  // Helper to safely call tools with retries for transient errors
  async function callToolWithRetry(toolName, args, maxRetries = 2) {
    let attempt = 0;
    while (true) {
      try {
        trace.push(`Calling tool ${toolName} (attempt ${attempt + 1})`);
        const result = await tools.call(toolName, args);
        return result;
      } catch (err) {
        attempt++;
        const isTransient = err && (err.code === 'UPSTREAM_503' || err.code === 'TIMEOUT' || err.name === 'ToolError');
        if (isTransient && attempt <= maxRetries) {
          trace.push(`Tool ${toolName} failed with transient error ${err.code || err.message}. Retrying...`);
          continue;
        }
        trace.push(`Tool ${toolName} failed fatally: ${err.message || String(err)}`);
        throw err;
      }
    }
  }

  // Helper to parse numeric string/number cleanly
  function parseNumber(val) {
    if (typeof val === 'number' && !isNaN(val)) return val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/,/g, '').trim();
      const num = parseFloat(cleaned);
      if (!isNaN(num)) return num;
    }
    return null;
  }

  // 1. Validate inputs
  const inputs = task && task.inputs ? task.inputs : {};
  const city = typeof inputs.city === 'string' ? inputs.city.trim() : null;
  const daysRaw = parseNumber(inputs.days);

  if (!city) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid Indian city name.' },
      trace
    };
  }

  if (daysRaw === null || !Number.isInteger(daysRaw) || daysRaw < 1 || daysRaw > 5) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please specify the number of days as an integer between 1 and 5.' },
      trace
    };
  }

  const days = daysRaw;

  // 2. Geocode city in India (country_code: 'IN')
  let geocodeResults;
  try {
    geocodeResults = await callToolWithRetry('geocode_city', { city: city, country_code: 'IN' });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Failed to geocode city: ${err.message}` },
      trace
    };
  }

  if (!Array.isArray(geocodeResults) || geocodeResults.length === 0) {
    // Retry without country code restriction in case country_code filter failed or wasn't matched properly
    try {
      geocodeResults = await callToolWithRetry('geocode_city', { city: city });
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Failed to geocode city on fallback: ${err.message}` },
        trace
      };
    }
  }

  if (!Array.isArray(geocodeResults) || geocodeResults.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: `Could not find coordinates for city '${city}'.` },
      trace
    };
  }

  // Prefer match from India if available
  let match = geocodeResults.find(g => g && typeof g.country_code === 'string' && g.country_code.toUpperCase() === 'IN');
  if (!match) {
    match = geocodeResults[0];
  }

  const lat = parseNumber(match.latitude);
  const lon = parseNumber(match.longitude);

  if (lat === null || lon === null) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Geocoding returned invalid lat/lon coordinates.' },
      trace
    };
  }

  // 3. Fetch air quality data
  let aqData;
  try {
    aqData = await callToolWithRetry('air_quality', { latitude: lat, longitude: lon, days: days });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Failed to fetch air quality data: ${err.message}` },
      trace
    };
  }

  if (!aqData || !Array.isArray(aqData.daily) || aqData.daily.length === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Air quality forecast returned no daily data.' },
      trace
    };
  }

  // Take up to requested N days
  const dailyRecords = aqData.daily.slice(0, days);
  const pm25Values = [];

  for (const record of dailyRecords) {
    if (record && record.pm25_mean !== undefined && record.pm25_mean !== null) {
      const pmVal = parseNumber(record.pm25_mean);
      if (pmVal !== null) {
        pm25Values.push(pmVal);
      }
    }
  }

  if (pm25Values.length === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'No valid PM2.5 mean values found in forecast.' },
      trace
    };
  }

  // Calculate average of daily mean PM2.5 values
  const sum = pm25Values.reduce((acc, v) => acc + v, 0);
  const avg = sum / pm25Values.length;

  return {
    status: 'success',
    answer: {
      value: Number(avg.toFixed(2)),
      unit: 'ug/m3'
    },
    success_indicators: {
      city: match.name || city,
      country: match.country_code || 'IN',
      days_calculated: pm25Values.length,
      daily_means: pm25Values
    },
    trace
  };
}

