    };
  }

  // ---------- Air quality forecast ----------
  const airQuality = async () => {
    try {
      trace.push('Calling air_quality');
      const result = await tools.call('air_quality', {
        latitude: coords.latitude,
        longitude: coords.longitude,
        days
      });
      if (!result || !Array.isArray(result.daily)) {
        throw new Error('Invalid air_quality output');
      }
      // Validate each daily entry
      const daily = result.daily.map((d, idx) => {
        if (
          typeof d.date !== 'string' ||
          typeof d.pm25_mean !== 'number' ||
          typeof d.us_aqi_max !== 'number'
        ) {
          throw new Error(`Invalid daily data at index ${idx}`);
