  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Calendar error: ${e.message}`]
    };
  }

  // 3. US holidays (simple UTC date compare)
  const usHolidays = new Set();
  try {
    const years = new Set([
      new Date(winStartMs).getUTCFullYear(),
      new Date(winEndMs).getUTCFullYear()
    ]);
    for (const y of years) {
      trace.push(`Holidays ${y}`);
      const hols = await callTool('public_holidays', { country_code: 'US', year: y });
      if (Array.isArray(hols)) {
        for (const h of hols) {
          if (h?.date) usHolidays.add(h.date);
        }
      }
    }
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Holiday error: ${e.message}`]
    };
  }

  // Helpers
  function fmtUTC(date) {
    const y = date.getUTCFullYear();
    const m = String(date.getUTCMonth() + 1).padStart(2, '0');
    const d = String(date.getUTCDate()).padStart(2, '0');
    const hh = String(date.getUTCHours()).padStart(2, '0');
    const mm = String(date.getUTCMinutes()).padStart(2, '0');
    return `${y}-${m}-${d}T${hh}:${mm}Z`;
  }

  function utcDateStr(ms) {
    const d = new Date(ms);
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(d.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${dd}`;
  }

  function isUSHoliday(startMs, endMs) {
    // Approximate: compare UTC date strings to holiday list
    const startStr = utcDateStr(startMs);
    const endStr = utcDateStr(endMs - 1);
    return usHolidays.has(startStr) || usHolidays.has(endStr);
  }

  function withinWorkingHours(startMs, endMs, prof) {
    const offset = prof.utc_offset_minutes * 60 * 1000;
    const localStart = new Date(startMs + offset);
    const localEnd = new Date(endMs + offset);
    if (
      localStart.getUTCFullYear() !== localEnd.getUTCFullYear() ||
      localStart.getUTCMonth() !== localEnd.getUTCMonth() ||
      localStart.getUTCDate() !== localEnd.getUTCDate()
    ) {
      return false;
    }
    const [sh, sm] = prof.working_hours.start.split(':').map(Number);
    const [eh, em] = prof.working_hours.end.split(':').map(Number);
    const workStart = sh * 60 + sm;
    const workEnd = eh * 60 + em;
    const startMins = localStart.getUTCHours() * 60 + localStart.getUTCMinutes();
    const endMins = localEnd.getUTCHours() * 60 + localEnd.getUTCMinutes();
    return startMins >= workStart && endMins <= workEnd;
  }

  function hasConflict(startMs, endMs) {
    for (const cal of calendars) {
      const prof = profiles.find(p => p.person === cal.person);
      const offset = (prof?.utc_offset_minutes || 0) * 60 * 1000;
      for (const b of cal.busy) {
        let bStart, bEnd;
        if (b.all_day) {
          const [y, m, d] = b.start.split('T')[0].split('-').map(Number);
          const localStart = Date.UTC(y, m - 1, d, 0, 0, 0);
          const localEnd = Date.UTC(y, m - 1, d + 1, 0, 0, 0);
          bStart = localStart - offset;
          bEnd = localEnd - offset;
        } else {
          bStart = parseISO(b.start);
          bEnd = parseISO(b.end);
        }
        if (isNaN(bStart) || isNaN(bEnd)) continue;
        if (startMs < bEnd && endMs > bStart) return true;
      }
    }
    return false;
  }

  // 4. Search earliest :00/:30 slot
  let cand = new Date(winStartMs);
  const mins = cand.getUTCMinutes();
  if (mins > 0 && mins < 30) cand.setUTCMinutes(30, 0, 0);
  else if (mins > 30) cand.setUTCHours(cand.getUTCHours() + 1, 0, 0, 0);
  else cand.setUTCMinutes(mins, 0, 0);
  let candMs = cand.getTime();
  const step = 30 * 60 * 1000;
  let chosen = null;

  while (candMs + durMs <= winEndMs) {
    const endMs = candMs + durMs;
    if (!isUSHoliday(candMs, endMs)) {
      const allWork = profiles.every(p => withinWorkingHours(candMs, endMs, p));
      if (allWork && !hasConflict(candMs, endMs)) {
        chosen = {
          start: fmtUTC(new Date(candMs)),
          end: fmtUTC(new Date(endMs)),
          participants
        };
        break;
      }
    }
    candMs += step;
  }

  if (!chosen) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No slot fits constraints.' },
      trace: [...trace, 'No suitable slot found']
    };
  }

  // 5. Confirmation / send invite
  if (!context.confirmed) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: `Proposed slot ${chosen.start} to ${chosen.end}. Confirm to send invite?`,
        proposed_slot: chosen
      },
      trace: [...trace, 'Awaiting confirmation']
    };
  }

  try {
    trace.push('Sending invite');
    await callTool('send_invite', {
      participants: chosen.participants,
      start: chosen.start,
      end: chosen.end,
      title: 'Team Meeting'
    });
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Invite error: ${e.message}`]
    };
  }

  return {
    status: 'success',
    answer: chosen,
    success_indicators: { booked: true },
    trace: [...trace, 'Meeting booked']
  };
}

