    const workEndMinutes = endH * 60 + endM;

    return totalMinutes >= workStartMinutes && totalMinutes <= workEndMinutes;
  }

  // Helper: check if a date (UTC) falls on a US public holiday (judged by US Eastern date)
  function isUSHoliday(utcDate) {
    const nyDateStr = getUSEasternDateStr(utcDate);
    return holidayDates.has(nyDateStr);
