async function run(task, tools, context) {
  const trace = [];
  const participants = task.inputs.participants;
  const durationMinutes = task.inputs.duration_minutes;
  const windowStart = task.inputs.window_start;
  const windowEnd = task.inputs.window_end;

  // 1. Validate inputs
  if (!Array.isArray(participants) || participants.length === 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a non-empty array of participants.' },
      trace: ['Invalid or missing participants']
    };
  }
  if (!Number.isInteger(durationMinutes) || durationMinutes <= 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid positive integer for duration_minutes.' },
      trace: ['Invalid duration_minutes']
    };
  }
  if (typeof windowStart !== 'string' || typeof windowEnd !== 'string') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide valid UTC ISO strings for window_start and window_end.' },
      trace: ['Invalid window_start or window_end']
    };
  }

  const startDate = new Date(windowStart);
  const endDate = new Date(windowEnd);
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime()) || startDate >= endDate) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'window_start must be a valid ISO date string earlier than window_end.' },
      trace: ['window_start/window_end validation failed']
    };
  }

  // Helper with retries
  async function callTool(name, args) {
    let lastErr;
    for (let attempt = 0; attempt <= 2; attempt++) {
      try {
        return await tools.call(name, args);
      } catch (err) {
        lastErr = err;
        if (err && err.name === 'ToolError' && (err.code === 'TIMEOUT' || err.code === 'UPSTREAM_503')) {
          continue;
        }
        break;
      }
    }
    throw lastErr;
  }

  trace.push(`Fetching profiles for participants: ${participants.join(', ')}`);
  const profiles = {};
  for (const p of participants) {
    try {
      const res = await callTool('get_person_profile', { person: p });
      if (!res || typeof res.timezone !== 'string' || typeof res.utc_offset_minutes !== 'number' || !res.working_hours) {
        throw new Error('Invalid profile schema');
      }
      profiles[p] = res;
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Failed to get profile for ${p}: ${err.message}` },
        trace
      };
    }
  }

  // Determine years needed for US holidays (judged by US Eastern date)
  // US Eastern is America/New_York (UTC-5 or UTC-4). Let's fetch holidays for years spanning the window.
  const years = new Set();
  years.add(startDate.getUTCFullYear());
  years.add(endDate.getUTCFullYear());

  const holidaysByDate = new Set();
  for (const year of years) {
    try {
      trace.push(`Fetching US public holidays for year ${year}`);
      const hols = await callTool('public_holidays', { country_code: 'US', year });
      if (Array.isArray(hols)) {
        for (const h of hols) {
          if (h && typeof h.date === 'string') {
            holidaysByDate.add(h.date); // 'YYYY-MM-DD'
          }
        }
      }
    } catch (err) {
      trace.push(`Warning: failed to fetch holidays for year ${year}: ${err.message}`);
    }
  }

  // Fetch calendars
  const calendars = {};
  for (const p of participants) {
    try {
      trace.push(`Fetching calendar for ${p}`);
      const cal = await callTool('get_calendar', { person: p, start: windowStart, end: windowEnd });
      const busy = Array.isArray(cal?.busy) ? cal.busy : [];
      calendars[p] = busy.map(b => {
        return {
          start: String(b.start),
          end: String(b.end),
          all_day: !!b.all_day
        };
      });
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Failed to get calendar for ${p}: ${err.message}` },
        trace
      };
    }
  }

  // Helper to get US Eastern date string ('YYYY-MM-DD') for any UTC Date object
  function getUSEasternDateStr(dateObj) {
    // America/New_York offset: standard is -5 hours, daylight saving is -4 hours.
    // We can use Intl.DateTimeFormat to reliably get the YYYY-MM-DD in America/New_York.
    try {
      const fmt = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'America/New_York',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      });
      return fmt.format(dateObj); // returns 'YYYY-MM-DD'
    } catch (e) {
      // Fallback rough estimate if Intl fails
      const utcSec = dateObj.getTime();
      const nySec = utcSec - 5 * 3600 * 1000;
      return new Date(nySec).toISOString().slice(0, 10);
    }
  }

  // Iterate through possible slots inside window_start and window_end, stepping by 30 minutes
  // Slots must start on :00 or :30 UTC.
  // windowStart and windowEnd might not be on :00/:30, so align start upwards to the next :00/:30.
  let currentSlotStart = new Date(startDate.getTime());
  const minutes = currentSlotStart.getUTCMinutes();
  const extraMins = minutes % 30;
  if (extraMins !== 0 || currentSlotStart.getUTCSeconds() > 0 || currentSlotStart.getUTCMilliseconds() > 0) {
    // round up to next :00 or :30
    currentSlotStart.setUTCMinutes(minutes + (30 - extraMins), 0, 0);
  }

  const slotDurationMs = durationMinutes * 60 * 1000;
  const windowEndTime = endDate.getTime();

  trace.push(`Scanning slots starting from ${currentSlotStart.toISOString()} with duration ${durationMinutes}m`);

  while (currentSlotStart.getTime() + slotDurationMs <= windowEndTime) {
    const slotStartMs = currentSlotStart.getTime();
    const slotEndMs = slotStartMs + slotDurationMs;
    const slotStartDateObj = new Date(slotStartMs);
    const slotEndDateObj = new Date(slotEndMs);

    const slotStartIso = slotStartDateObj.toISOString().replace(/\.\d{3}Z$/, 'Z');
    const slotEndIso = slotEndDateObj.toISOString().replace(/\.\d{3}Z$/, 'Z');

    // Check US Eastern Holiday constraint
    const usDateStr = getUSEasternDateStr(slotStartDateObj);
    const usEndDateStr = getUSEasternDateStr(slotEndDateObj);
    // If either the start date or end date falls on a US holiday, skip
    if (holidaysByDate.has(usDateStr) || holidaysByDate.has(usEndDateStr)) {
      // Advance by 30 minutes
      currentSlotStart = new Date(currentSlotStart.getTime() + 30 * 60 * 1000);
      continue;
    }

    // Check everyone's working hours and busy times
    let slotValid = true;
    for (const p of participants) {
      const profile = profiles[p];
      // Convert slot start/end to person's local time
      // person profile has timezone and utc_offset_minutes
      // Let's check local working hours. Working hours format: 'HH:mm'
      // We can use Intl.DateTimeFormat for the person's timezone to get local HH:mm and YYYY-MM-DD.
      const localPartsStart = getLocalParts(slotStartDateObj, profile.timezone);
      const localPartsEnd = getLocalParts(slotEndDateObj, profile.timezone);

      // If meeting spans across different local days for working hours check, or outside working hours:
      // Note: working hours apply to the meeting duration. Both start and end must be within working hours on the same local date.
      if (localPartsStart.dateStr !== localPartsEnd.dateStr) {
        slotValid = false;
        break;
      }

      const whStart = profile.working_hours.start; // 'HH:mm'
      const whEnd = profile.working_hours.end;     // 'HH:mm'

      if (localPartsStart.timeStr < whStart || localPartsStart.timeStr > whEnd ||
