      // Check busy intervals
      const busyList = calendars[p];
      for (const b of busyList) {
        if (b.all_day) {
          // all_day event: b.start is 'YYYY-MM-DD'. Check if localPartsStart.dateStr matches or overlaps.
          if (b.start === localPartsStart.dateStr) {
            slotValid = false;
            break;
          }
        } else {
          const bStartMs = new Date(b.start).getTime();
          const bEndMs = new Date(b.end).getTime();
          // Overlap check: max(slotStart, bStart) < min(slotEnd, bEnd)
          const overlapStart = Math.max(slotStartMs, bStartMs);
          const overlapEnd = Math.min(slotEndMs, bEndMs);
          if (overlapStart < overlapEnd) {
            slotValid = false;
            break;
          }
        }
      }

      if (!slotValid) break;
    }

    if (slotValid) {
      trace.push(`Found earliest valid slot: ${slotStartIso} to ${slotEndIso}`);

      // Check if we need to send invite (side effect)
      // Spec says: "books the earliest slot... send_invite requires explicit user confirmation"
      // Wait, does the agent always book it via send_invite? 
      // Let's check agent spec and instructions. "send_invite({participants: array, start: string, end: string, title?: string})"
      // SIDE EFFECT: requires explicit user confirmation (context.confirmed === true).
      if (context.confirmed) {
        try {
          trace.push('User confirmed. Sending invite...');
          await callTool('send_invite', {
            participants,
            start: slotStartIso,
            end: slotEndIso,
            title: 'Team Meeting'
          });
        } catch (err) {
          return {
            status: 'failed_gracefully',
            answer: null,
            success_indicators: { error: `Failed to send invite: ${err.message}` },
            trace
          };
        }
      } else {
