      }

      return {
        status: 'success',
        answer: {
          start: slotStartIso,
          end: slotEndIso,
          participants
        },
        success_indicators: { booked: context.confirmed },
        trace
      };
    }

    // Advance by 30 minutes
    currentSlotStart = new Date(currentSlotStart.getTime() + 30 * 60 * 1000);
  }

  trace.push('No available slot found satisfying all constraints.');
  return {
    status: 'infeasible',
    answer: null,
    success_indicators: { reason: 'No slot found satisfying working hours, holiday, and conflict constraints.' },
    trace
  };
}

function getLocalParts(dateObj, timezone) {
  try {
    const dateFmt = new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    });
    const timeFmt = new Intl.DateTimeFormat('en-GB', {
      timeZone: timezone,
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
    return {
      dateStr: dateFmt.format(dateObj), // 'YYYY-MM-DD'
      timeStr: timeFmt.format(dateObj)  // 'HH:mm'
    };
  } catch (e) {
    // Fallback using UTC if timezone invalid
    const iso = dateObj.toISOString();
    return {
      dateStr: iso.slice(0, 10),
      timeStr: iso.slice(11, 16)
    };
  }
}

