    if (t.getUTCHours() * 60 + t.getUTCMinutes() % slotInterval !== 0) continue; // ensure :00 or :30
    const slotEnd = new Date(t.getTime() + duration_minutes * 60000);
    if (slotEnd > endTime) break;
    candidateSlots.push({ start: new Date(t), end: new Date(slotEnd) });
  }

  // ---------- Check Availability ----------
  function isSlotFree(slot) {
    for (const person of participants) {
      const profile = profiles[person];
      const offset = profile.utc_offset_minutes;
      const localStart = utcToLocalMinutes(slot.start, offset);
      const localEnd = utcToLocalMinutes(slot.end, offset);
      const [workStart, workEnd] = profile.working_hours.start.split(':').map(Number);
      const [workEndH, workEndM] = profile.working_hours.end.split(':').map(Number);
      const workStartMin = workStart * 60 + workStart;
      const workEndMin = workEndH * 60 + workEndM;
      if (localStart < workStartMin || localEnd > workEndMin) return false;
      for (const ev of busyMap[person]) {
        if (slot.start < ev.end && slot.end > ev.start) return false;
      }
    }
    return true;
  }

  const availableSlot = candidateSlots.find(isSlotFree);

  if (!availableSlot) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  const resultAnswer = {
    start: availableSlot.start.toISOString().replace('.000', ''),
    end: availableSlot.end.toISOString().replace('.000', ''),
    participants
  };

  // ---------- Send Invite if Confirmed ----------
  if (context.confirmed) {
    try {
      const inviteRes = await callWithRetry('send_invite', {
