      if (!inviteRes || inviteRes.status !== 'sent') throw new Error('Invite not sent');
      trace.push(`Invite sent: ${inviteRes.invite_id}`);
    } catch (e) {
      trace.push(`Failed to send invite: ${e.message}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
  }

  return { status: 'success', answer: resultAnswer, success_indicators: {}, trace };
