/**
 * Agent to find the earliest meeting slot satisfying:
 * - No calendar conflicts for any participant
 * - Within each participant's working hours (local)
 * - Does NOT overlap each participant's local lunch break 12:30‑14:00
 * - Slot start must be on minute 00 or 30 (UTC)
 *
 * @param {Object} task   { text:string, inputs:{ participants:string[], duration_minutes:number, window_start:string, window_end:string } }
 * @param {Object} tools  { call(name:string, args:Object):Promise<any> }
