  const intersectIntervals = (a, b) => {
    const res = [];
    let i = 0,
      j = 0;
    while (i < a.length && j < b.length) {
      const start = a[i].start > b[j].start ? a[i].start : b[j].start;
      const end = a[i].end < b[j].end ? a[i].end : b[j].end;
      if (start < end) res.push({ start, end });
      if (a[i].end < b[j].end) i++;
      else j++;
    }
    return res;
  };
  const complementIntervals = (busy, overallStart, overallEnd) => {
    const free = [];
    let cursor = overallStart;
    for (const b of busy) {
      if (b.start > cursor) free.push({ start: cursor, end: b.start });
      cursor = b.end > cursor ? b.end : cursor;
    }
    if (cursor < overallEnd) free.push({ start: cursor, end: overallEnd });
    return free;
  };
  const validateToolOutput = (obj, schema) => {
    for (const [k, type] of Object.entries(schema)) {
      if (!(k in obj)) return false;
      const val = obj[k];
      if (type === 'string') {
        if (typeof val !== 'string') return false;
      } else if (type === 'number') {
        if (typeof val === 'number') continue;
        if (typeof val === 'string') {
          // coerce numeric strings, allow commas
          const num = Number(val.replace(/,/g, ''));
          if (Number.isNaN(num)) return false;
          obj[k] = num;
        } else return false;
      } else if (type === 'boolean') {
