  const windowEnd = parseISO(inputs.window_end);
  if (windowStart >= windowEnd) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'window_start must be before window_end' },
      trace,
    };
  }

  // ---------- fetch profiles ----------
  const profiles = {};
  for (const person of inputs.participants) {
    try {
      const raw = await callTool('get_person_profile', { person });
      if (!validateToolOutput(raw, { person: 'string', timezone: 'string', utc_offset_minutes: 'number', working_hours: 'object' })) {
