      }
      profiles[person] = raw;
    } catch (e) {
      trace.push(`Failed to get profile for ${person}: ${e.message}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
  }

  // ---------- build per‑person unavailable intervals ----------
  const overallBusy = []; // will hold merged busy intervals in UTC
  for (const person of inputs.participants) {
    const prof = profiles[person];
    const offset = prof.utc_offset_minutes; // minutes to add to UTC to get local
    // compute local working window in UTC for each day in the global window
    const dayStart = new Date(Date.UTC(windowStart.getUTCFullYear(), windowStart.getUTCMonth(), windowStart.getUTCDate()));
    const dayEnd = new Date(Date.UTC(windowEnd.getUTCFullYear(), windowEnd.getUTCMonth(), windowEnd.getUTCDate() + 1));
    const localWorkStart = prof.working_hours.start; // HH:mm local
    const localWorkEnd = prof.working_hours.end;
    const lunchStart = '12:30';
    const lunchEnd = '14:00';

    // helper to convert local HH:mm on a given UTC day to UTC Date
    const localToUTC = (utcDay, hhmm) => {
      const [hh, mm] = hhmm.split(':').map(Number);
      const local = new Date(Date.UTC(
        utcDay.getUTCFullYear(),
        utcDay.getUTCMonth(),
        utcDay.getUTCDate(),
        hh,
        mm
      ));
      // shift by -offset to get UTC instant
      return new Date(local.getTime() - offset * 60000);
    };

    // collect unavailable intervals for this person
    const personBusy = [];

    // 1. Outside working hours (treated as busy)
    for (let d = new Date(dayStart); d < dayEnd; d.setUTCDate(d.getUTCDate() + 1)) {
      const workStartUTC = localToUTC(d, localWorkStart);
      const workEndUTC = localToUTC(d, localWorkEnd);
      // before workStart
      if (workStartUTC > windowStart) personBusy.push({ start: windowStart, end: workStartUTC });
      // after workEnd
      if (workEndUTC < windowEnd) personBusy.push({ start: workEndUTC, end: windowEnd });
      // lunch break (always busy)
      const lunchStartUTC = localToUTC(d, lunchStart);
      const lunchEndUTC = localToUTC(d, lunchEnd);
      personBusy.push({ start: lunchStartUTC, end: lunchEndUTC });
    }

    // 2. Calendar busy intervals
    try {
      const cal = await callTool('get_calendar', {
        person,
        start: inputs.window_start,
        end: inputs.window_end,
      });
      if (!Array.isArray(cal.busy)) {
        trace.push(`Calendar busy list not array for ${person}`);
        return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
      }
      for (const ev of cal.busy) {
        // Validate fields
        if (!ev.start || !ev.end) continue; // skip malformed
        const evStart = parseISO(ev.start);
        const evEnd = parseISO(ev.end);
        if (isNaN(evStart) || isNaN(evEnd) || evStart >= evEnd) continue;
        personBusy.push({ start: evStart, end: evEnd });
      }
    } catch (e) {
      trace.push(`Calendar fetch failed for ${person}: ${e.message}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }

    // 3. Normalize intervals: sort & merge overlapping
    personBusy.sort((a, b) => a.start - b.start);
    const merged = [];
    for (const iv of personBusy) {
      if (merged.length === 0) merged.push(iv);
      else {
        const last = merged[merged.length - 1];
        if (iv.start <= last.end) {
          if (iv.end > last.end) last.end = iv.end;
        } else merged.push(iv);
      }
    }
    overallBusy.push(...merged);
  }

  // ---------- merge all participants' busy intervals ----------
  overallBusy.sort((a, b) => a.start - b.start);
  const mergedBusy = [];
  for (const iv of overallBusy) {
    if (mergedBusy.length === 0) mergedBusy.push(iv);
    else {
      const last = mergedBusy[mergedBusy.length - 1];
      if (iv.start <= last.end) {
        if (iv.end > last.end) last.end = iv.end;
      } else mergedBusy.push(iv);
    }
  }

  // ---------- compute free slots ----------
  const freeSlots = complementIntervals(mergedBusy, windowStart, windowEnd);

  // ---------- find earliest slot that aligns on :00 or :30 and fits duration ----------
  const durMs = inputs.duration_minutes * 60000;
  for (const slot of freeSlots) {
    // round start up to next 0/30 minute
    let candidateStart = roundUpToSlot(new Date(slot.start));
    while (candidateStart.getTime() + durMs <= slot.end.getTime()) {
      const candidateEnd = new Date(candidateStart.getTime() + durMs);
      // verify that candidate respects each participant's local lunch break (already added as busy)
      // and working hours (already added as busy). So we only need to ensure alignment.
      // Return earliest found.
      return {
        status: 'success',
        answer: {
          start: toISO(candidateStart),
          end: toISO(candidateEnd),
          participants: inputs.participants,
        },
        success_indicators: { found: true },
        trace,
      };
    }
  }

  // ---------- no feasible slot ----------
  return {
    status: 'infeasible',
    answer: null,
    success_indicators: { reason: 'no slot satisfies all constraints' },
    trace,
  };
}

