  };

  // Function to check if slot collides with busy intervals
  const collidesBusy = (person, slotStart, slotEnd) => {
    for (const ev of busyIntervals[person]) {
      if (ev.all_day) {
        // All day events block entire day
        const evStart = new Date(ev.start);
        const evEnd = new Date(ev.end);
        if (slotStart < evEnd && slotEnd > evStart) return true;
      } else {
        const evStart = ev.start;
        const evEnd = ev.end;
        if (slotStart < evEnd && slotEnd > evStart) return true;
      }
    }
    return false;
  };

  // ---------- Iterate over candidate slots ----------
  let candidateStart = new Date(Math.ceil(winStart.getTime() / msPerHalfHour) * msPerHalfHour);
  while (candidateStart.getTime() + durationMs <= winEnd.getTime()) {
    const candidateEnd = new Date(candidateStart.getTime() + durationMs);
    let slotValid = true;

    for (const person of participants) {
      // Working hours
      if (!isWithinWorkingHours(person, candidateStart)) {
        slotValid = false;
        break;
      }
      // Lunch break
      if (isDuringLunch(person, candidateStart)) {
        slotValid = false;
        break;
      }
      // Busy intervals
      if (collidesBusy(person, candidateStart, candidateEnd)) {
        slotValid = false;
        break;
      }
    }

    if (slotValid) {
      const answer = {
        start: candidateStart.toISOString().replace(/\.\d{3}Z$/, 'Z'),
        end: candidateEnd.toISOString().replace(/\.\d{3}Z$/, 'Z'),
        participants: [...participants]
      };
      return { status: 'success', answer, success_indicators: {}, trace };
    }

    candidateStart = new Date(candidateStart.getTime() + msPerHalfHour);
  }

  // No slot found
  return { status: 'infeasible', answer: null, success_indicators: {}, trace };
}
